import{_ as t,o as d,c as o,a2 as c}from"./chunks/framework.DGk0zlJw.js";const u=JSON.parse('{"title":"Beacon 组件化重构 · 现状清单与目标模型映射（Phase 0 交付）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/design/redesign-2026-10-16-映射与迁移.md","filePath":"zh/design/redesign-2026-10-16-映射与迁移.md"}'),r={name:"zh/design/redesign-2026-10-16-映射与迁移.md"};function a(i,e,n,s,l,h){return d(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="beacon-组件化重构-·-现状清单与目标模型映射-phase-0-交付" tabindex="-1">Beacon 组件化重构 · 现状清单与目标模型映射（Phase 0 交付） <a class="header-anchor" href="#beacon-组件化重构-·-现状清单与目标模型映射-phase-0-交付" aria-label="Permalink to &quot;Beacon 组件化重构 · 现状清单与目标模型映射（Phase 0 交付）&quot;">​</a></h1><p><strong>依据</strong>：<code>docs/design/redesign-plan-2026-10-16.md</code>（外部设计稿）+ <code>docs/design/redesign-2026-10-16-核验.md</code>（50 条现状核验，commit <code>759742b</code>） <strong>清单时点</strong>：2026-10-16，基于 commit <code>759742b</code> 的代码面。 <strong>性质</strong>：本文是 todo「组件化重构分期」Phase 0 的交付物——现状清单、目标模型映射表、差异与迁移计划。<strong>第 5、6 节原为提案；2026-10-16 PATROL1016 已代决四条并冻结契约，决策记录与冻结面见 <code>docs/design/redesign-2026-10-16-契约.md</code>（HTML 边界一条仍留问）。</strong></p><hr><h2 id="_1-现状清单" tabindex="-1">1. 现状清单 <a class="header-anchor" href="#_1-现状清单" aria-label="Permalink to &quot;1. 现状清单&quot;">​</a></h2><h3 id="_1-1-项目与文件数" tabindex="-1">1.1 项目与文件数 <a class="header-anchor" href="#_1-1-项目与文件数" aria-label="Permalink to &quot;1.1 项目与文件数&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>文件数</th><th>职责</th><th>依赖</th></tr></thead><tbody><tr><td><code>Beacon.Core</code></td><td>47</td><td>领域模型 + 抽象 + 服务（无 UI、无 Provider 依赖）</td><td>仅 BCL + Logging.Abstractions（<code>Beacon.Core.csproj:7</code>）</td></tr><tr><td><code>Beacon.App</code></td><td>28</td><td>WinUI 3 壳（唯一 exe）、托盘 / 热键 / 六窗 / 组装根</td><td>四个类库 + WindowsAppSDK</td></tr><tr><td><code>Beacon.Connections</code></td><td>34</td><td>23 类 Widget Provider + 17 类连接 Provider</td><td>仅 Core</td></tr><tr><td><code>Beacon.Actions</code></td><td>5</td><td>4 个通用 Action 执行器</td><td>仅 Core</td></tr><tr><td><code>Beacon.Storage</code></td><td>6</td><td>JSON 配置 / 缓存 / DPAPI 密钥库 / 导入导出</td><td>仅 Core + ProtectedData</td></tr></tbody></table><h3 id="_1-2-widget-provider-23-个类型键" tabindex="-1">1.2 Widget Provider（23 个类型键） <a class="header-anchor" href="#_1-2-widget-provider-23-个类型键" aria-label="Permalink to &quot;1.2 Widget Provider（23 个类型键）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型键</th><th>Provider</th><th>连接</th></tr></thead><tbody><tr><td><code>github.pull_requests</code> / <code>github.actions.runs</code></td><td>GitHubPullRequestsProvider / GitHubActionsProvider</td><td>github</td></tr><tr><td><code>http.status</code> / <code>http.quota</code></td><td>HttpStatusProvider / HttpQuotaProvider</td><td>http</td></tr><tr><td><code>jenkins.build</code></td><td>JenkinsBuildProvider</td><td>jenkins</td></tr><tr><td><code>bigmodel.usage</code></td><td>BigModelUsageProvider</td><td>bigmodel</td></tr><tr><td><code>ark.usage</code></td><td>ArkUsageProvider</td><td>ark</td></tr><tr><td><code>claude.usage</code></td><td>ClaudeUsageProvider</td><td>claude</td></tr><tr><td><code>deepseek.balance</code></td><td>DeepSeekBalanceProvider</td><td>deepseek</td></tr><tr><td><code>kimi.coding</code></td><td>KimiCodingUsageProvider</td><td>kimi</td></tr><tr><td><code>moonshot.balance</code></td><td>MoonshotBalanceProvider</td><td>moonshot</td></tr><tr><td><code>mimo.usage</code></td><td>MiMoUsageProvider</td><td>mimo</td></tr><tr><td><code>codex.usage</code></td><td>CodexUsageProvider</td><td>codex</td></tr><tr><td><code>copilot.usage</code></td><td>CopilotUsageProvider</td><td>copilot</td></tr><tr><td><code>opencode.usage</code></td><td>OpenCodeUsageProvider</td><td>opencode</td></tr><tr><td><code>qwen.usage</code></td><td>QwenUsageProvider</td><td>qwen</td></tr><tr><td><code>sensenova.tokenplan</code></td><td>SenseNovaUsageProvider</td><td>sensenova</td></tr><tr><td><code>machine.net</code> / <code>machine.local</code> / <code>machine.git</code></td><td>MachineNetProvider / MachineLocalProvider / GitWorkspaceProvider</td><td>machine（零凭据）</td></tr><tr><td><code>herald.incidents</code> / <code>herald.feed</code> / <code>herald.deliveries</code></td><td>HeraldIncidentsProvider / HeraldFeedProvider / HeraldDeliveriesProvider</td><td>herald</td></tr></tbody></table><p>注册表：<code>src/Beacon.App/Services/BeaconRuntime.cs:116-141</code>。</p><h3 id="_1-3-连接-provider-17-类" tabindex="-1">1.3 连接 Provider（17 类） <a class="header-anchor" href="#_1-3-连接-provider-17-类" aria-label="Permalink to &quot;1.3 连接 Provider（17 类）&quot;">​</a></h3><p><code>github</code> <code>http</code> <code>jenkins</code> <code>bigmodel</code> <code>ark</code> <code>claude</code> <code>deepseek</code> <code>kimi</code> <code>moonshot</code> <code>mimo</code> <code>codex</code> <code>copilot</code> <code>opencode</code> <code>qwen</code> <code>sensenova</code> <code>machine</code> <code>herald</code>（注册于 <code>BeaconRuntime.cs:183</code> 起）。</p><h3 id="_1-4-action-执行器-7-个-type-字符串" tabindex="-1">1.4 Action 执行器（7 个 Type 字符串） <a class="header-anchor" href="#_1-4-action-执行器-7-个-type-字符串" aria-label="Permalink to &quot;1.4 Action 执行器（7 个 Type 字符串）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>执行器</th><th>出处</th></tr></thead><tbody><tr><td><code>open.url</code></td><td>OpenUrlExecutor</td><td><code>src/Beacon.Actions/OpenUrlExecutor.cs:13</code></td></tr><tr><td><code>local.command</code></td><td>LocalCommandExecutor</td><td><code>src/Beacon.Actions/LocalCommandExecutor.cs:11</code></td></tr><tr><td><code>http</code></td><td>HttpExecutor</td><td><code>src/Beacon.Actions/HttpExecutor.cs:12</code></td></tr><tr><td><code>webhook</code></td><td>WebhookExecutor</td><td><code>src/Beacon.Actions/WebhookExecutor.cs:16</code></td></tr><tr><td><code>gh.workflow_dispatch</code></td><td>GitHubWorkflowDispatchExecutor</td><td><code>src/Beacon.Connections/GitHubWorkflowExecutors.cs:70</code></td></tr><tr><td><code>gh.workflow_rerun</code></td><td>GitHubWorkflowRerunExecutor</td><td><code>src/Beacon.Connections/GitHubWorkflowExecutors.cs:98</code></td></tr><tr><td><code>gh.workflow_cancel</code></td><td>GitHubWorkflowCancelExecutor</td><td><code>src/Beacon.Connections/GitHubWorkflowExecutors.cs:121</code></td></tr></tbody></table><h3 id="_1-5-显示面-windows-全在-src-beacon-app-windows" tabindex="-1">1.5 显示面（Windows，全在 <code>src/Beacon.App/Windows/</code>） <a class="header-anchor" href="#_1-5-显示面-windows-全在-src-beacon-app-windows" aria-label="Permalink to &quot;1.5 显示面（Windows，全在 `src/Beacon.App/Windows/`）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>窗口</th><th>层</th><th>角色</th></tr></thead><tbody><tr><td>CapsuleWindow</td><td>L1</td><td>状态胶囊（聚合 Severity + 计数）</td></tr><tr><td>PinnedHostWindow</td><td>L0</td><td>桌面钉选宿主面板（多 tile、两列布局、WM_NCHITTEST 穿透）</td></tr><tr><td>FloatingTileWindow</td><td>L0</td><td>单组件悬浮窗（可拖拽、边缘坍缩）</td></tr><tr><td>QuickPanelWindow</td><td>L2</td><td>快捷面板（事件看板、过滤、RECENT、需要关注区）</td></tr><tr><td>DetailWindow</td><td>L3</td><td>单组件详情 + 动作执行反馈</td></tr><tr><td>SettingsWindow</td><td>—</td><td>设置（连接 / 组件向导 / 外观 / 通知规则）</td></tr></tbody></table><p>通用行渲染 <code>MakeStateRow</code>（<code>QuickPanelWindow.cs:471</code>）是 L2 状态行与事件行的唯一构造点——<strong>这是组件化改造的主替换面</strong>。</p><h3 id="_1-6-beacon-core-服务清单-24-个-services-8-抽象-13-模型-事件-json" tabindex="-1">1.6 Beacon.Core 服务清单（24 个 Services + 8 抽象 + 13 模型 + 事件 + Json） <a class="header-anchor" href="#_1-6-beacon-core-服务清单-24-个-services-8-抽象-13-模型-事件-json" aria-label="Permalink to &quot;1.6 Beacon.Core 服务清单（24 个 Services + 8 抽象 + 13 模型 + 事件 + Json）&quot;">​</a></h3><ul><li>抽象（8）：<code>IActionExecutor</code> <code>ICacheStore</code> <code>IClock</code> <code>IConfigurationStore</code> <code>IConnectionProvider</code>（内含 <code>IWidgetProvider</code> / <code>IWidgetProviderResolver</code>）<code>IEventBus</code>（内含 <code>IUiDispatcher</code>）<code>INotificationSink</code> <code>ISecretStore</code></li><li>模型（13）：<code>ActionModels</code> <code>AppConfig</code> <code>ConnectionConfig</code> <code>ConnectionHealthState</code> <code>LifecycleState</code> <code>NotificationModels</code> <code>PinLayout</code> <code>RefreshTiers</code> <code>Severity</code> <code>WidgetConfig</code> <code>WidgetDisplayPolicy</code> <code>WidgetState</code> <code>WidgetTypeDescriptor</code></li><li>服务（24）：<code>ActionRunner</code> <code>ActionVisibility</code> <code>BrandIcons</code> <code>ContrastMath</code> <code>DebugInjection</code> <code>DispatchGuard</code> <code>DpiLayoutMath</code> <code>EventBus</code> <code>HighContrastPalette</code> <code>NotificationEngine</code> <code>PaletteResolver</code> <code>PinLayoutMath</code> <code>QuickPanelFilter</code> <code>QuickPanelSections</code> <code>QuotaWindows</code> <code>RefreshScheduler</code> <code>StatusAggregator</code> <code>SvgPathParser</code> <code>TemplateRenderer</code> <code>UiStrings</code> <code>UpdateCheck</code> <code>WidgetHost</code> <code>WidgetTypeNames</code> <code>WidgetValueHint</code></li><li>其余：<code>Events/Events.cs</code>（6 个事件记录，含 <code>ActionExecuted</code>）、<code>Json/BeaconJson.cs</code></li></ul><h3 id="_1-7-持久化面-9-处-日志" tabindex="-1">1.7 持久化面（9 处 + 日志） <a class="header-anchor" href="#_1-7-持久化面-9-处-日志" aria-label="Permalink to &quot;1.7 持久化面（9 处 + 日志）&quot;">​</a></h3><p><code>config.json</code> <code>connections.json</code> <code>widgets.json</code> <code>pins.json</code> <code>actions.json</code> <code>notifications.json</code>（六个 JSON）；<code>cache/&lt;connectionId&gt;/states.json</code>（<code>JsonCacheStore.cs:76</code>）；<code>secrets.bin</code>（DPAPI，<code>DpapiSecretStore.cs:22</code>）；<code>shell-state.json</code>（胶囊布局，<code>ShellStateStore.cs:18</code>）；日志 <code>%APPDATA%\\Beacon\\logs\\beacon-YYYYMMDD.log</code>。</p><hr><h2 id="_2-状态模型字段定性-业务状态-显示字段-本地偏好-元数据" tabindex="-1">2. 状态模型字段定性（业务状态 / 显示字段 / 本地偏好 / 元数据） <a class="header-anchor" href="#_2-状态模型字段定性-业务状态-显示字段-本地偏好-元数据" aria-label="Permalink to &quot;2. 状态模型字段定性（业务状态 / 显示字段 / 本地偏好 / 元数据）&quot;">​</a></h2><h3 id="_2-1-widgetstate-src-beacon-core-models-widgetstate-cs-4-21" tabindex="-1">2.1 <code>WidgetState</code>（<code>src/Beacon.Core/Models/WidgetState.cs:4-21</code>） <a class="header-anchor" href="#_2-1-widgetstate-src-beacon-core-models-widgetstate-cs-4-21" aria-label="Permalink to &quot;2.1 `WidgetState`（`src/Beacon.Core/Models/WidgetState.cs:4-21`）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>定性</th><th>说明</th></tr></thead><tbody><tr><td><code>WidgetId</code> <code>WidgetType</code> <code>ConnectionId</code></td><td>标识</td><td>稳定键，非状态</td></tr><tr><td><code>Severity</code> <code>Lifecycle</code></td><td><strong>业务状态</strong></td><td>外部系统事实的标准化投影</td></tr><tr><td><code>Progress</code></td><td><strong>业务状态</strong></td><td>0..1 归一化进度</td></tr><tr><td><code>Payload</code></td><td><strong>业务数据</strong></td><td>供 Action 模板变量（run_id 等）</td></tr><tr><td><code>Summary</code></td><td><strong>显示字段</strong></td><td>已本地化文案，混入业务状态对象（设计稿 §实施建议的拆分点）</td></tr><tr><td><code>DetailUrl</code></td><td>业务元数据</td><td>外部详情链接，Open 动作消费</td></tr><tr><td><code>FetchedAt</code></td><td>元数据</td><td>新鲜度；<strong>参与内容相等比较</strong>（<code>:36</code>，核验表 B09 反向证据）</td></tr><tr><td><code>IsStale</code> <code>ConnectionHealthy</code></td><td><strong>派生状态</strong></td><td>由失败 / 离线推导，非外部事实</td></tr></tbody></table><h3 id="_2-2-配置字段-appconfig-cs-widgetconfig-cs" tabindex="-1">2.2 配置字段（<code>AppConfig.cs</code> / <code>WidgetConfig.cs</code>） <a class="header-anchor" href="#_2-2-配置字段-appconfig-cs-widgetconfig-cs" aria-label="Permalink to &quot;2.2 配置字段（`AppConfig.cs` / `WidgetConfig.cs`）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类别</th><th>字段</th></tr></thead><tbody><tr><td><strong>本地偏好（Preference）</strong></td><td><code>Theme</code> <code>UiOpacity</code> <code>Appearance.*</code>（SeverityColors / Motion.Mode / Motion.Intensity / ProgressStyle）<code>Language</code> <code>EdgeCollapseEnabled</code> <code>NumericFloatingEnabled</code> <code>PinDisplayMode</code> <code>ShowCapsule</code> <code>SettingsSidebarWidth</code> <code>SettingsWindowWidth/Height</code>；<code>WidgetConfig.Pinned</code> <code>PinLayout</code> <code>ColorOverride</code></td></tr><tr><td>全局设置（用户意图）</td><td><code>Hotkey</code> <code>LaunchOnStartup</code> <code>PollIntervalSeconds</code> <code>NotificationRules</code></td></tr><tr><td>业务配置</td><td><code>WidgetConfig.Config</code>（Provider 参数）、<code>ConnectionConfig</code> 全部</td></tr><tr><td>调度配置</td><td><code>WidgetConfig.RefreshTier</code> <code>RefreshIntervalSeconds</code></td></tr></tbody></table><p><strong>结论</strong>：<code>Summary</code> 是业务状态对象里唯一的显示字段；本地偏好已与业务配置分文件存放（<code>config.json</code> vs <code>connections.json</code>/<code>widgets.json</code>），隔离现状良好，Phase 1 只需处理 <code>Summary</code> 与派生字段的口径，不需要动配置文件结构。</p><hr><h2 id="_3-目标模型映射表-现有实现-→-新架构槽位" tabindex="-1">3. 目标模型映射表（现有实现 → 新架构槽位） <a class="header-anchor" href="#_3-目标模型映射表-现有实现-→-新架构槽位" aria-label="Permalink to &quot;3. 目标模型映射表（现有实现 → 新架构槽位）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现有实现</th><th>新架构槽位（设计稿 §10）</th><th>迁移动作</th></tr></thead><tbody><tr><td><code>IConnectionProvider</code> / <code>IWidgetProvider</code>（<code>IConnectionProvider.cs:12,29</code>）</td><td>Data Acquisition: Connection / Widget Providers</td><td><strong>保留不动</strong></td></tr><tr><td><code>RefreshScheduler</code>（<code>RefreshScheduler.cs:17</code>）</td><td>Data Acquisition: Refresh Scheduler</td><td>保留；<code>Kick</code> 语义即「Action 后定向刷新」，无需新机制</td></tr><tr><td><code>ICacheStore</code> / <code>JsonCacheStore</code></td><td>Data Acquisition: Cache</td><td>保留</td></tr><tr><td><code>ISecretStore</code> / <code>DpapiSecretStore</code></td><td>Security: Secret Store</td><td>保留</td></tr><tr><td><code>WidgetHost</code>（<code>WidgetHost.cs:12</code>）</td><td>Data Acquisition 生命周期 + 状态发布</td><td><strong>拆分候选</strong>：数据获取 / 生命周期保留；「统一状态入口」职责让位 State Store（Phase 1）</td></tr><tr><td><code>EventBus</code> + <code>Events.cs</code>（<code>IEventBus.cs:4</code>）</td><td>Reactive Core: Event Stream</td><td>保留</td></tr><tr><td><code>StatusAggregator</code>（<code>StatusAggregator.cs:11</code>）</td><td>Reactive Core: Derived State / Aggregation</td><td>保留；快照语义可并入 State Store 或维持独立</td></tr><tr><td><code>WidgetState.Equals</code>（<code>WidgetState.cs:24-58</code>）</td><td>Reactive Core: Change Detection</td><td><strong>改造点</strong>：<code>FetchedAt</code> 移出内容相等（见 §4 Phase 1）</td></tr><tr><td><code>NotificationEngine</code>（<code>NotificationEngine.cs:14</code>）</td><td>Signal &amp; Notification</td><td>保留</td></tr><tr><td><code>ActionRunner</code> + 7 执行器（<code>ActionRunner.cs:15</code>）</td><td>Command &amp; Action: Dispatcher / Executor</td><td>保留；<code>ActionResult</code> 五态化属契约变更，待拍板</td></tr><tr><td><code>WidgetTypeDescriptor</code>（<code>WidgetTypeDescriptor.cs:15</code>）</td><td>Display Composition: Component Contracts</td><td><strong>演进点</strong>：从「设置表单元数据 + L0 准入」演进为显示组件能力声明（Phase 3 Component Descriptor 的前身）</td></tr><tr><td><code>MakeStateRow</code>（<code>QuickPanelWindow.cs:471</code>）</td><td>Display Composition: 显示组件</td><td><strong>替换点</strong>：通用行渲染 → 组件库第一批（Phase 2）</td></tr><tr><td>六个 Window（§1.5）</td><td>Windows UI: Pinned Tiles / Floating / Quick Panel / Detail / Settings</td><td>保留；仅渲染段接组件库</td></tr><tr><td><code>UiPalette</code> <code>ThemeColors</code> <code>MotionEngine</code> <code>DpiLayoutMath</code> <code>ContrastMath</code> <code>HighContrastPalette</code></td><td>Design System: 设计令牌</td><td><strong>收编点</strong>：散常量 → 统一令牌体系（Phase 2）</td></tr><tr><td><code>QuotaWindows</code> <code>WidgetValueHint</code> <code>QuickPanelSections</code> <code>QuickPanelFilter</code></td><td>Reactive Core: Selectors</td><td><strong>收编点</strong>：第一批 Selector 的现成素材（Phase 1）</td></tr><tr><td>—（无对应实现）</td><td>State Store / Binding Engine / Component Registry / HTML Renderer Host</td><td><strong>新建</strong>（Phase 1-4）</td></tr></tbody></table><hr><h2 id="_4-差异与迁移计划-按期" tabindex="-1">4. 差异与迁移计划（按期） <a class="header-anchor" href="#_4-差异与迁移计划-按期" aria-label="Permalink to &quot;4. 差异与迁移计划（按期）&quot;">​</a></h2><h3 id="phase-1-响应式状态与数据流" tabindex="-1">Phase 1 响应式状态与数据流 <a class="header-anchor" href="#phase-1-响应式状态与数据流" aria-label="Permalink to &quot;Phase 1 响应式状态与数据流&quot;">​</a></h3><ol><li>引入 <code>IStateStore</code>（进程内实现）：快照读取 + 订阅 + 内容级变更检测。<code>WidgetHost</code> 刷新成功后改写入 Store，Store 判变后发 <code>WidgetStateChanged</code>——<strong>发布点从 WidgetHost 移到 Store</strong>，事件契约不变，UI 无感。</li><li>变更检测口径：<code>WidgetState</code> 内容相等移除 <code>FetchedAt</code>（或加 <code>ContentVersion</code>），使「仅刷新时间变化」不再触发下游。</li><li>Selector 收编：<code>QuotaWindows</code> / <code>WidgetValueHint</code> / <code>QuickPanelSections</code> / <code>QuickPanelFilter</code> 归位为 Selector 层，签名不动，只挪命名空间与文档定位。</li><li><strong>回归面</strong>：去重后 UI 不再每 tick 重建——场景 S（事件流）、O（面板计数）、Q（胶囊计数）必须全绿；F5（断网降级恰 1 条通知）依赖 stale 事件不被去重吞掉，需单测先行。</li><li>回退：Store 引入为旁路（一次 commit 可整体回退），不合并进 WidgetHost 改写。</li></ol><h3 id="phase-2-设计系统与基础组件库" tabindex="-1">Phase 2 设计系统与基础组件库 <a class="header-anchor" href="#phase-2-设计系统与基础组件库" aria-label="Permalink to &quot;Phase 2 设计系统与基础组件库&quot;">​</a></h3><ol><li>令牌化：<code>UiPalette</code> / <code>ThemeColors</code> / <code>MotionEngine</code> / <code>DpiLayoutMath</code> 收编为令牌层；<strong>色值不得变</strong>（G 系 CI 像素断言锚现有色值，改值即红）。</li><li>第一批组件从 <code>MakeStateRow</code> 反推：Metric、Status Indicator、Progress、Key-Value、Status Card、List、Action Button、Link、Stack、Grid、Section、Conditional、Empty、Loading、Error、Offline。</li><li>视觉示例页独立成窗（仅 debug 构建），不进产品窗口集。</li></ol><h3 id="phase-3-组件组合与数据绑定" tabindex="-1">Phase 3 组件组合与数据绑定 <a class="header-anchor" href="#phase-3-组件组合与数据绑定" aria-label="Permalink to &quot;Phase 3 组件组合与数据绑定&quot;">​</a></h3><ol><li><code>Component Descriptor</code>：在 <code>WidgetTypeDescriptor</code> 之上加显示声明（组件类型 + 绑定 + 密度），<strong>不推翻既有 23 个类型键</strong>。</li><li><code>WidgetConfig</code> 增量可选字段（<code>ConfigVersion</code> 递增，旧文件可读）——兼容方案见 §5。</li><li>Selector 到组件属性绑定 + 多数据源组合（<code>WidgetState</code> 单 <code>ConnectionId</code> 的现状不破坏，组合发生在组件层聚合多个 WidgetId）。</li></ol><h3 id="phase-4-html-小屏幕" tabindex="-1">Phase 4 HTML 小屏幕 <a class="header-anchor" href="#phase-4-html-小屏幕" aria-label="Permalink to &quot;Phase 4 HTML 小屏幕&quot;">​</a></h3><p><strong>前置拍板</strong>：与 <code>docs/master-plan.md:769</code>「不引入 WebView 或其他 UI 框架来重复实现桌面外壳」的边界裁定——HTML 只进「数据显示小屏幕」不进「外壳」，还是整体维持原生。裁定前不开工。</p><h3 id="phase-5-6" tabindex="-1">Phase 5 / 6 <a class="header-anchor" href="#phase-5-6" aria-label="Permalink to &quot;Phase 5 / 6&quot;">​</a></h3><p>组件目录扩展与全量回归；装机清单 71 条（<code>docs/acceptance-checklist.md</code>）继续作为验收底座，Phase 6 逐条复跑。</p><hr><h2 id="_5-兼容方案-提案-待拍板" tabindex="-1">5. 兼容方案（提案，待拍板） <a class="header-anchor" href="#_5-兼容方案-提案-待拍板" aria-label="Permalink to &quot;5. 兼容方案（提案，待拍板）&quot;">​</a></h2><ol><li>六个 JSON 文件名与既有字段语义<strong>全部不变</strong>（延续核验表 G02 已实现口径）。</li><li>新组件模型以 <code>WidgetConfig</code> 增量可选字段进入，<code>ConfigVersion</code> 递增但旧版本可读；不迁移、不重命名。</li><li>既有 23 个类型键、7 个 Action Type 字符串、全部窗口层级保留；组件化只替换渲染段与状态入口，不动 Provider 与执行器。</li><li>真机验收能力保留：71 条装机清单与 CI 视觉取证场景继续有效，Phase 6 全量回归后才算期次完成。</li></ol><h2 id="_6-待拍板清单-2026-10-16-patrol1016-已代决1234-仅第-3-条留问" tabindex="-1">6. 待拍板清单（2026-10-16 PATROL1016 已代决①②③④，仅第 3 条留问） <a class="header-anchor" href="#_6-待拍板清单-2026-10-16-patrol1016-已代决1234-仅第-3-条留问" aria-label="Permalink to &quot;6. 待拍板清单（2026-10-16 PATROL1016 已代决①②③④，仅第 3 条留问）&quot;">​</a></h2><ol><li><s><strong>契约冻结范围</strong></s> → 已代决①③：<code>IStateStore</code> 契约冻结 = 落地签名；<code>ActionResult</code> 目标五态、Phase 5 落地（契约.md §4）。</li><li><s><strong><code>FetchedAt</code> 移出内容相等</strong></s> → 已代决②：<code>d71bdc8</code> 起去重默认启用，回退开关保留（契约.md §4）。</li><li><strong>HTML 小屏幕与 master-plan:769 的边界</strong>：数据显示面允许 HTML、外壳维持原生，还是整体维持原生。<strong>超范围，仍待用户裁定（Phase 4 开工前）。</strong></li><li><s><strong>§5 兼容方案</strong>四条是否照此冻结</s> → 已代决④：照此冻结（契约.md §3）。</li></ol>',47)])])}const p=t(r,[["render",a]]);export{u as __pageData,p as default};
